// Turns /semantic/prompts/*.md into app/src/lib/ai/prompts.generated.ts so the prompts in /semantic stay the single source of truth
// (the app deploys from /app, which cannot read ../semantic at runtime). If ../semantic is not available the committed generated file is kept.
import { readdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const dir = join(here, "..", "..", "semantic", "prompts");
const out = join(here, "..", "src", "lib", "ai", "prompts.generated.ts");
if (!existsSync(dir)) { console.log("sync-prompts: ../semantic/prompts not found, keeping the committed prompts.generated.ts"); process.exit(0); }

const section = (text, name) => {
  const m = text.match(new RegExp(`^## ${name}\\s*\\n([\\s\\S]*?)(?=^## |\\Z)`, "m"));
  return m ? m[1].trim() : "";
};
const prompts = {};
for (const f of readdirSync(dir).filter((x) => x.endsWith(".md") && x !== "README.md").sort()) {
  const text = readFileSync(join(dir, f), "utf8");
  const id = f.replace(/\.md$/, "");
  prompts[id] = {
    id,
    required: section(text, "Required context").split(",").map((s) => s.trim()).filter(Boolean),
    template: section(text, "Template"),
    system: section(text, "System prompt"),
  };
}
writeFileSync(out, `// GENERATED by scripts/sync-prompts.mjs from /semantic/prompts/*.md. Do not edit by hand.\nexport type PromptDef = { id: string; required: string[]; template: string; system: string };\nexport const PROMPTS: Record<string, PromptDef> = ${JSON.stringify(prompts, null, 2)};\n`);
console.log(`sync-prompts: wrote ${Object.keys(prompts).length} prompts (${Object.keys(prompts).join(", ")})`);
